@@ -253,7 +253,7 @@ NS_IMETHODIMP StoreIndexer::OnStopRequest(nsIRequest* req, nsresult status) {
   // Clear up our per-message vars.
   mStoreToken.Truncate();
   mCurrentMsgSize = 0;
-  mParser->m_newMsgHdr = nullptr;
+  mParser->SetNewMsgHdr(nullptr);
   mParser = nullptr;
   return NS_OK;
 }
