     mCopyState->m_parseMsgState->m_envelope_pos =
         mCopyState->m_parseMsgState->m_position;

-    if (mCopyState->m_parseMsgState->m_newMsgHdr) {
-      mCopyState->m_parseMsgState->m_newMsgHdr->GetMessageKey(
